#!/usr/bin/env python3
"""Shared CV PDF extraction helpers for the cv-jd-interview-screening skill.

Design rules:
- Explicit errors (missing/empty/corrupt/zero-page PDF, no text layer) are
  returned, never fabricated into an empty success.
- Text is returned per page; candidate identity is anchored by file content
  (sha256), never by filename conventions.
- Whitespace normalization is shared with evidence_check.py so literal quotes
  are matched identically in both tools.
- Display filtering (watermark heuristic) applies to the cleaned text/lines
  only; raw per-page text is retained so legitimate evidence is never erased
  and literal quote checks always see the real PDF text.
"""

import hashlib
import re
import sys
from pathlib import Path

try:
    import pymupdf
except ImportError:  # pragma: no cover
    pymupdf = None


class ExtractError(Exception):
    """Raised with a precise reason when a PDF cannot be extracted."""


# A watermark line: a single long alphanumeric token alone on one line,
# typical of resume-platform trackers. Dropped from cleaned (display) text.
_WATERMARK_RE = re.compile(r"^[A-Za-z0-9_-]{24,}$")


def normalize(text):
    """Collapse all whitespace so quotes match across PDF line breaks."""
    return re.sub(r"\s+", "", text)


def clean_page_text(raw):
    lines = []
    for line in raw.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if _WATERMARK_RE.match(stripped):
            continue
        lines.append(stripped)
    return lines


def extract_pdf(path):
    """Extract per-page text from one PDF path. Raises ExtractError."""
    if pymupdf is None:
        raise ExtractError("pymupdf not available in this environment")
    p = Path(path)
    if not p.exists():
        raise ExtractError(f"file not found: {p}")
    try:
        data = p.read_bytes()
    except OSError as exc:
        raise ExtractError(f"unreadable file: {p}: {exc}")
    if len(data) == 0:
        raise ExtractError(f"empty file (0 bytes): {p}")
    if not data.startswith(b"%PDF-"):
        raise ExtractError(f"not a PDF (bad header): {p}")
    try:
        doc = pymupdf.open(stream=data, filetype="pdf")
    except Exception as exc:
        raise ExtractError(f"corrupt/unopenable PDF: {p}: {exc}")
    if doc.page_count == 0:
        raise ExtractError(f"PDF has zero pages: {p}")
    pages = []
    saw_any_text = False
    for i, page in enumerate(doc):
        raw = page.get_text()
        if raw.strip():
            saw_any_text = True
        cleaned = clean_page_text(raw)
        pages.append({
            "page": i + 1,
            "lines": cleaned,
            "text": "\n".join(cleaned),
            # Unfiltered page text is retained so display filtering can never
            # erase legitimate evidence (literal quotes validate against it).
            "raw_text": raw,
        })
    doc.close()
    if not saw_any_text:
        # No text layer anywhere: a scanned/image-only PDF. This is an explicit
        # unusable state (needs OCR), never a quiet empty success.
        raise ExtractError(
            f"no usable text layer (scanned image; needs OCR): {p}")
    sha = hashlib.sha256(data).hexdigest()
    identity_lines = pages[0]["lines"][:6]
    return {
        "file": str(p),
        "candidate_id": "cv_" + sha[:12],
        "sha256": sha,
        "bytes": len(data),
        "page_count": len(pages),
        "identity_lines": identity_lines,
        "pages": pages,
    }


def extract_many(paths):
    """Extract a batch. Returns (results, errors); candidates never mix
    because each result carries its own candidate_id and page list."""
    results, errors = [], []
    for path in paths:
        try:
            results.append(extract_pdf(path))
        except ExtractError as exc:
            errors.append({"file": str(path), "error": str(exc)})
    return results, errors


def find_quote(cv, quote, page=None):
    """Locate a normalized literal quote. Returns dict with ok/reason and the
    page(s) where the quote actually occurs (for mismatch diagnostics).
    Matching runs against each page's raw_text so display-side filtering
    (e.g. the watermark heuristic) cannot hide real PDF text from evidence
    checks."""
    norm = normalize(quote)
    if not norm:
        return {"ok": False, "reason": "empty quote"}
    hits = [
        pg["page"] for pg in cv["pages"]
        if norm in normalize(pg.get("raw_text", pg["text"]))
    ]
    if page is not None and (page < 1 or page > cv["page_count"]):
        return {
            "ok": False,
            "reason": f"page {page} out of range (1..{cv['page_count']})",
            "found_pages": hits,
        }
    if page is not None:
        if page in hits:
            return {"ok": True, "page": page}
        return {"ok": False, "reason": "quote not on claimed page", "found_pages": hits}
    if hits:
        return {"ok": True, "page": hits[0]}
    return {"ok": False, "reason": "quote not found in document", "found_pages": []}


if __name__ == "__main__":
    print("cvlib is a library; run cv_extract.py or evidence_check.py", file=sys.stderr)
    sys.exit(1)

#!/usr/bin/env python3
"""Validate literal quotes cited from CV PDFs (quote/page/candidate claims).

Usage:
  evidence_check.py CLAIMS.json [--json OUT.json]

CLAIMS.json: JSON array of claim objects
  [{"file": "path/to/cv.pdf", "quote": "literal text from the CV",
    "page": 2}, ...]

Public claim contract (small, checked before any extraction):
- each item must be a JSON object (mapping);
- "file" and "quote" must be nonempty strings;
- "page" is optional; when present it must be a positive JSON integer
  (booleans, floats, strings and zero are rejected).
Quotes are whitespace-normalized (line breaks inside a quote are fine), and
matching runs against the PDF's raw per-page text, so display filtering never
hides legitimate evidence.
Fails on: contract violations, quote not found, quote on a different page than
claimed, out-of-range page, or any file-level extraction error
(missing/empty/corrupt/no-text-layer).
Exit codes: 0 all claims valid; 2 any failure. Failure report goes to stdout
as JSON; contract errors carry the claim index plus "field" and a precise
"reason" (no uncaught traceback).
"""

import argparse
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import cvlib


def claim_shape_error(claim):
    """Return (field, reason) for the first contract violation, else None."""
    if not isinstance(claim, dict):
        return ("claim", "claim item must be an object (mapping)")
    file_val = claim.get("file")
    if not isinstance(file_val, str) or not file_val.strip():
        return ("file", "file must be a nonempty string")
    quote_val = claim.get("quote")
    if not isinstance(quote_val, str) or not quote_val.strip():
        return ("quote", "quote must be a nonempty string")
    if "page" in claim:
        page_val = claim["page"]
        if isinstance(page_val, bool) or not isinstance(page_val, int):
            kind = "boolean" if isinstance(page_val, bool) else type(page_val).__name__
            return ("page", f"page must be an integer, not {kind}")
        if page_val < 1:
            return ("page", "page must be a positive integer (>= 1)")
    return None


def main():
    ap = argparse.ArgumentParser(description="Check literal CV quotes against pages")
    ap.add_argument("claims", help="JSON file with claim array")
    ap.add_argument("--json", dest="json_out", help="also write JSON report to this path")
    args = ap.parse_args()

    claims_path = Path(args.claims)
    if not claims_path.exists():
        print(json.dumps({"ok": False, "error": "claims file not found: " + str(claims_path)},
                         ensure_ascii=False))
        return 2
    try:
        claims = json.loads(claims_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as exc:
        print(json.dumps({"ok": False, "error": "claims file unreadable: " + str(exc)},
                         ensure_ascii=False))
        return 2
    if not isinstance(claims, list):
        print(json.dumps({"ok": False, "error": "claims must be a JSON array"},
                         ensure_ascii=False))
        return 2

    cache = {}
    report, any_fail = [], False
    for idx, claim in enumerate(claims):
        shape = claim_shape_error(claim)
        if shape is not None:
            field, reason = shape
            entry = {
                "index": idx,
                "path": ["claims", idx],
                "field": field,
                "ok": False,
                "reason": reason,
            }
            if isinstance(claim, dict) and isinstance(claim.get("file"), str):
                entry["file"] = claim["file"]
            report.append(entry)
            any_fail = True
            continue
        entry = {"index": idx, "file": claim["file"], "ok": False}
        path = claim["file"]
        if path not in cache:
            try:
                cache[path] = (cvlib.extract_pdf(path), None)
            except cvlib.ExtractError as exc:
                cache[path] = (None, str(exc))
        cv, err = cache[path]
        if err:
            entry["reason"] = "file error: " + err
            any_fail = True
        else:
            entry["candidate_id"] = cv["candidate_id"]
            res = cvlib.find_quote(cv, claim["quote"], claim.get("page"))
            entry.update(res)
            if not res["ok"]:
                any_fail = True
        report.append(entry)

    out = {"ok": not any_fail, "claims": report}
    payload = json.dumps(out, ensure_ascii=False, indent=2)
    if args.json_out:
        Path(args.json_out).write_text(payload, encoding="utf-8")
    print(payload)
    return 0 if not any_fail else 2


if __name__ == "__main__":
    sys.exit(main())
